INSERT INTO kpi_templates (template_name, department, position, kpi_name, target_standard, weight_percentage, scoring_scale, transition_notes) VALUES ('Revenue Growth', 'Executive', 'Director', 'Revenue Growth', 'Sesuai RUPS (Toleransi 80% dari target ideal)', 40.0, '{"1": "<50%", "2": "50-69%", "3": "70-85%", "4": "86-100%", "5": ">100%"}', 'Fase transisi - fokus pembentukan kebiasaan');
