INSERT INTO kpi_templates (template_name, department, position, kpi_name, target_standard, weight_percentage, scoring_scale, transition_notes) VALUES ('Pipeline Development', 'Executive', 'Director', 'Pipeline Contribution', 'Minimal 5 pipeline dengan kontribusi minimal 10% dari total revenue', 10.0, '{"1": "0-1 pipeline", "2": "2-3 pipeline", "3": "4-5 pipeline", "4": "6-8 pipeline", "5": ">8 pipeline"}', 'Pipeline aktif dari network pribadi');
